<script setup>
import { useRouter } from 'vue-router'
import { useCatalog } from '../composables/catalog.js'
import PageTitle from '../components/PageTitle.vue'
import LoadState from '../components/LoadState.vue'
import CollectionCharts from '../components/CollectionCharts.vue'
import ProfileCorrelation from '../components/ProfileCorrelation.vue'
const {catalog,loading,error,reload}=useCatalog(),router=useRouter()
</script>
<template><PageTitle eyebrow="COLLECTION STATISTICS" title="Explore data coverage" description="Understand the collection using studies, profiles and raw cell labels as counting units."/><LoadState :loading="loading" :error="error" @retry="reload"><template v-if="catalog"><CollectionCharts :catalog="catalog" @select="filters=>router.push({path:'/samples',query:filters})"/><section class="panel latest-panel"><div class="panel-head"><div><h2>Compare the two existing catalogs</h2><p>Each catalog retains its provenance; the catalogs are not summed or merged</p></div><span class="status-tag">Version mapping pending review</span></div><div class="table-scroll"><table><thead><tr><th>Catalog / metric</th><th>Older 93-sample catalog</th><th>Current 105-profile catalog</th></tr></thead><tbody><tr><td>Record count</td><td>93</td><td>105</td></tr><tr><td>GEO study</td><td>{{ catalog.older_catalog.studies }}</td><td>{{ catalog.summary.studies }}</td></tr><tr v-for="a in ['GRO-seq','PRO-seq','mNET-seq']" :key="a"><td>{{ a }}</td><td>{{ catalog.older_catalog.assays[a] }}</td><td>{{ catalog.summary.assays[a] }}</td></tr></tbody></table></div><div class="version-diff"><div><h3>GSEs exclusive to the 105 catalog <span>{{ catalog.comparison.only_in_105.length }}</span></h3><div class="cell-tags"><RouterLink v-for="gse in catalog.comparison.only_in_105" :key="gse" :to="`/studies/${gse}`">{{ gse }}</RouterLink></div></div><div><h3>GSEs exclusive to the 93 catalog <span>{{ catalog.comparison.only_in_93.length }}</span></h3><div class="cell-tags"><a v-for="gse in catalog.comparison.only_in_93" :key="gse" :href="`https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=${gse}`" target="_blank" rel="noopener">{{ gse }} ↗</a></div></div></div></section><section id="cell-coverage" class="panel latest-panel"><div class="panel-head"><h2>Profile coverage across all cell labels</h2><span class="small">{{ catalog.cells.length }} raw labels</span></div><div class="full-coverage"><RouterLink class="interactive-tag" v-for="cell in [...catalog.cells].sort((a,b)=>catalog.profiles.filter(p=>p.cell===b).length-catalog.profiles.filter(p=>p.cell===a).length)" :key="cell" :to="{path:'/samples',query:{cell}}"><span>{{ cell }}</span><b>{{ catalog.profiles.filter(p=>p.cell===cell).length }}</b></RouterLink></div></section><ProfileCorrelation :catalog="catalog"/></template></LoadState></template>
